import Foundation
import UIKit
import XCTest

/// 合成夹具：只生成不含真实票据或个人信息的高对比图片与 PDF。
enum SyntheticFixtures {
    static let totalLine = "TOTAL 12.50"
    static let imageSize = CGSize(width: 900, height: 520)
    private static let textAttributes: [NSAttributedString.Key: Any] = [
        .font: UIFont.systemFont(ofSize: 96, weight: .bold),
        .foregroundColor: UIColor.black,
    ]

    static func pngData(variant: Int = 0) throws -> Data {
        try XCTUnwrap(renderImage(variant: variant).pngData())
    }

    static func jpegData(variant: Int = 0) throws -> Data {
        try XCTUnwrap(renderImage(variant: variant).jpegData(compressionQuality: 0.9))
    }

    /// 保留前 `fraction` 字节的 JPEG：魔数完好，但扫描数据不完整。
    static func truncatedJPEGData(keepingFraction fraction: Double) throws -> Data {
        let data = try jpegData()
        return Data(data.prefix(Int(Double(data.count) * fraction)))
    }

    static func pdfData(pages: Int = 1) -> Data {
        let renderer = UIGraphicsPDFRenderer(bounds: CGRect(x: 0, y: 0, width: 600, height: 800))
        return renderer.pdfData { context in
            for page in 0..<max(pages, 1) {
                context.beginPage()
                ("\(totalLine) PAGE \(page + 1)" as NSString)
                    .draw(at: CGPoint(x: 60, y: 320), withAttributes: textAttributes)
            }
        }
    }

    /// 合成加密 PDF（白页 + 标准安全处理器 + 用户口令），仅用于验证“加密文件不可导入”。
    static func encryptedPDFData() throws -> Data {
        try XCTUnwrap(Data(base64Encoded: encryptedPDFBase64))
    }

    /// 合成 HEIC（240×120 合成文字图，品牌 heic），仅用于验证合法 HEIC 可导入。
    static func heicData() throws -> Data {
        try XCTUnwrap(Data(base64Encoded: heicBase64))
    }

    private static let encryptedPDFBase64 = ""

    private static let heicBase64 = ""

    /// variant 改变金额文本，使同尺寸图片字节互异；默认 0 与既有夹具一致。
    private static func renderImage(variant: Int = 0) -> UIImage {
        UIGraphicsImageRenderer(size: imageSize).image { context in
            UIColor.white.setFill()
            context.fill(CGRect(origin: .zero, size: imageSize))
            let line = variant == 0 ? totalLine : "TOTAL \(12.5 + Double(variant))"
            (line as NSString).draw(at: CGPoint(x: 40, y: 200), withAttributes: textAttributes)
        }
    }
}

/// 每个用例独立临时目录，结束时整体删除。
struct FixtureDirectory {
    let url: URL

    init() throws {
        url = FileManager.default.temporaryDirectory
            .appendingPathComponent("TryInvoiceFixtures-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: url, withIntermediateDirectories: true)
    }

    func write(_ data: Data, named name: String) throws -> URL {
        let target = url.appendingPathComponent(name)
        try data.write(to: target)
        return target
    }

    func remove() {
        try? FileManager.default.removeItem(at: url)
    }
}
